export function CreateOrderFormDialog({ isOpen, onClose, onSuccess }: CreateOrderDialogProps) {
  const [formData, setFormData] = useState<CreateOrderFormData>(createEmptyOrderForm())
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Reset form when dialog opens
  useEffect(() => {
    if (isOpen) {
      setFormData(createEmptyOrderForm())
      setError(null)
    }
  }, [isOpen])

  // Deposit amount tracking — lease validation happens server-side (409 error)
  const depositAmount = formData.depositAmount ?? null
  const hasDeposit = depositAmount != null && depositAmount > 0
  const showPaymentMethod = hasDeposit

  // Add a new line item row
  const addLineItem = () => {
    setFormData(prev => ({
      ...prev,
      lineItems: [...prev.lineItems, {
        lineType: 'part',
        description: '',
        quantity: 1,
        unitPriceNet: 0,
        vatRateId: '',
      }],
    }))
  }

  // Update a specific line item
  const updateLineItem = (index: number, updates: Partial<OrderLineItemForm>) => {
    setFormData(prev => ({
      ...prev,
      lineItems: prev.lineItems.map((item, i) => i === index ? { ...item, ...updates } : item),
    }))
  }

  // Remove a line item
  const removeLineItem = (index: number) => {
    setFormData(prev => ({
      ...prev,
      lineItems: prev.lineItems.filter((_, i) => i !== index),
    }))
  }

  // Compute total net from line items
  const totalNet = formData.lineItems.reduce((sum, item) => sum + (item.unitPriceNet * item.quantity), 0)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)

    try {
      // Validate required fields
      if (!formData.customerId) throw new Error('Customer is required')
      if (formData.lineItems.length === 0) throw new Error('At least one line item is required')
      for (const item of formData.lineItems) {
        if (!item.description.trim()) throw new Error('All line items must have a description')
        if (item.unitPriceNet <= 0) throw new Error('Unit price must be greater than 0')
      }

      const orderInput = {
        customerId: formData.customerId,
        lineItems: formData.lineItems.map(item => ({
          lineType: item.lineType,
          partId: item.partId ?? null,
          laborServiceId: item.laborServiceId ?? null,
          description: item.description,
          quantity: item.quantity,
          unitPriceNet: item.unitPriceNet,
          vatRateId: item.vatRateId,
          discountPercent: item.discountPercent ?? null,
          bicycleId: item.bicycleId ?? null,
          bicycleBrand: item.bicycleBrand ?? null,
          bicycleModel: item.bicycleModel ?? null,
          bicycleYear: item.bicycleYear ?? null,
          bicycleColor: item.bicycleColor ?? null,
          bicycleFrameSize: item.bicycleFrameSize ?? null,
        })),
        depositAmount: (depositAmount != null && depositAmount > 0) ? depositAmount : undefined,
        paymentMethod: showPaymentMethod ? formData.paymentMethod : undefined,
      }

      const result = await createOrder(orderInput)
      onSuccess(result.order.id)
      onClose()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create order')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>New Customer Order</DialogTitle>
          <DialogDescription>
            Create a customer order for parts or bicycles not in stock. Optionally collect a deposit upfront.
          </DialogDescription>
        </DialogHeader>

        {error && (
          <div className="rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          {/* Customer Selector */}
          <CustomerSelector
            selectedCustomerId={formData.customerId}
            onSelect={(customerId) => setFormData(prev => ({ ...prev, customerId }))}
          />

          {/* Line Items */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label className="text-sm font-medium text-muted-foreground">Line Items</Label>
              <Button type="button" variant="outline" size="sm" onClick={addLineItem} className="h-7 px-2 text-xs gap-1">
                <Plus className="h-3 w-3" /> Add Item
              </Button>
            </div>

            {formData.lineItems.length === 0 ? (
              <div className="text-center py-6 border rounded-md border-dashed text-sm text-muted-foreground">
                No line items yet. Click "Add Item" to start.
              </div>
            ) : (
              <div className="space-y-2">
                {formData.lineItems.map((item, index) => (
                  <LineItemRow key={index} item={item} onUpdate={(updates) => updateLineItem(index, updates)} onRemove={() => removeLineItem(index)} />
                ))}

                {/* Total */}
                <div className="flex justify-end pt-2 border-t text-sm">
                  <span className="text-muted-foreground mr-auto">Total (net):</span>
                  <span className="font-mono font-medium">{formatCentsToEuro(totalNet)}</span>
                </div>
              </div>
            )}
          </div>

          {/* Deposit Section */}
          <div className="space-y-3 border-t pt-4">
            <Label className="text-sm font-medium text-muted-foreground">Deposit (optional)</Label>

            <div className="flex items-center gap-3">
              <input type="number" value={depositAmount ?? ''} onChange={(e) => {
                const val = e.target.value === '' ? null : Math.max(0, parseInt(e.target.value) || 0)
                setFormData(prev => ({ ...prev, depositAmount: val }))
              }} min={0} placeholder="0"
                className="w-32 h-9 px-3 text-sm rounded border font-mono focus:border-ring focus:outline-none" />
              <span className="text-xs text-muted-foreground">cents</span>
            </div>

            {/* Payment Method (only shown when deposit > 0) */}
            {showPaymentMethod && (
              <div className="space-y-2 pt-2 border-t">
                <Label className="text-sm font-medium text-muted-foreground">Deposit Payment Method</Label>
                <div className="grid grid-cols-3 gap-2">
                  {(['cash', 'card', 'bank_transfer'] as const).map((method) => (
                    <Button key={method} type="button" variant={formData.paymentMethod === method ? 'default' : 'outline'} size="sm"
                      onClick={() => setFormData(prev => ({ ...prev, paymentMethod: method }))}>
                      {method === 'cash' ? '💵 Cash' : method === 'card' ? '💳 Card' : '🏦 Transfer'}
                    </Button>
                  ))}
                </div>

                {/* Deposit summary */}
                <div className="mt-2 p-3 bg-accent rounded-md text-sm">
                  <div className="flex justify-between mb-1">
                    <span className="text-muted-foreground">Deposit:</span>
                    <span className="font-mono font-medium">{formatCentsToEuro(depositAmount!)}</span>
                  </div>
                  <div className="flex justify-between text-xs text-muted-foreground">
                    <span>Balance due at pickup:</span>
                    <span className="font-mono">{formatCentsToEuro(Math.max(0, totalNet - depositAmount!))}</span>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Actions */}
          <DialogFooter className="gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={onClose} disabled={submitting}>
              Cancel
            </Button>
            <Button type="submit" disabled={submitting || !formData.customerId || formData.lineItems.length === 0}>
              {submitting ? 'Creating...' : 'Create Order'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}
