      const { createCustomerOrder, listCustomerOrders, updateCustomerOrderStatus } = await import('../customer-order.service.js')

      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      // Create two orders
      const order1 = await createCustomerOrder({
        customerId: 'cust-abc-123',
